const upsertAccountLockout = `-- name: UpsertAccountLockout :exec
INSERT INTO iam.account_lockout (
    organization_id, identity_id, failed_attempts, lockout_tier,
    lockout_until, last_failed_at, updated_at
) VALUES (
    $1::uuid, $2::uuid, $3::int,
    $4::int, $5::timestamptz,
    $6::timestamptz, $7::timestamptz
)
ON CONFLICT (organization_id, identity_id) DO UPDATE
SET failed_attempts = $3::int,
    lockout_tier = $4::int,
    lockout_until = $5::timestamptz,
    last_failed_at = $6::timestamptz,
    updated_at = $7::timestamptz
`

type UpsertAccountLockoutParams struct {
	OrganizationID dbuuid.UUID        `json:"organization_id"`
	IdentityID     dbuuid.UUID        `json:"identity_id"`
	FailedAttempts int32              `json:"failed_attempts"`
	LockoutTier    int32              `json:"lockout_tier"`
	LockoutUntil   pgtype.Timestamptz `json:"lockout_until"`
	LastFailedAt   pgtype.Timestamptz `json:"last_failed_at"`
	UpdatedAt      pgtype.Timestamptz `json:"updated_at"`
}

// Creates or updates the lockout record after a failed attempt.
func (q *Queries) UpsertAccountLockout(ctx context.Context, db DBTX, arg *UpsertAccountLockoutParams) error {
	_, err := db.Exec(ctx, upsertAccountLockout,
		arg.OrganizationID,
		arg.IdentityID,
		arg.FailedAttempts,
		arg.LockoutTier,
		arg.LockoutUntil,
		arg.LastFailedAt,
		arg.UpdatedAt,
	)
	return err
}

const upsertUserPreference = `-- name: UpsertUserPreference :one
INSERT INTO iam.user_preference (
    id,
    organization_id,
    employee_id,
    theme_mode,
    preference_source,
    additional_preferences,
    updated_at
) VALUES (
    $1, $2, $3, $4, $5, $6, $7
) ON CONFLICT (organization_id, employee_id) DO UPDATE SET
    theme_mode = EXCLUDED.theme_mode,
    preference_source = EXCLUDED.preference_source,
    additional_preferences = EXCLUDED.additional_preferences,
    updated_at = EXCLUDED.updated_at
RETURNING id, organization_id, employee_id, theme_mode, preference_source, additional_preferences, updated_at
`

type UpsertUserPreferenceParams struct {
	ID                    dbuuid.UUID        `json:"id"`
	OrganizationID        dbuuid.UUID        `json:"organization_id"`
	EmployeeID            dbuuid.UUID        `json:"employee_id"`
	ThemeMode             string             `json:"theme_mode"`
	PreferenceSource      string             `json:"preference_source"`
	AdditionalPreferences []byte             `json:"additional_preferences"`
	UpdatedAt             pgtype.Timestamptz `json:"updated_at"`
}

// Insert or update user preference (theme mode, preference source)
// Handles first-time users and theme changes
// Uses parameterized updated_at per Citus constraint (no now() in ON CONFLICT DO UPDATE)
//
// Parameters:
// - $1 id (UUID): Record ID (uuidv7)
// - $2 organization_id (UUID, required): Tenant isolation
// - $3 employee_id (UUID, required): User identity
// - $4 theme_mode (text): "light" or "dark"
// - $5 preference_source (text): "manual" or "os_default"
// - $6 additional_preferences (jsonb): Future preferences extension
// - $7 updated_at (timestamptz): Parameterized timestamp
func (q *Queries) UpsertUserPreference(ctx context.Context, db DBTX, arg *UpsertUserPreferenceParams) (*IamUserPreference, error) {
	row := db.QueryRow(ctx, upsertUserPreference,
		arg.ID,
		arg.OrganizationID,
		arg.EmployeeID,
		arg.ThemeMode,
		arg.PreferenceSource,
		arg.AdditionalPreferences,
		arg.UpdatedAt,
	)
	var i IamUserPreference
	err := row.Scan(
		&i.ID,
		&i.OrganizationID,
		&i.EmployeeID,
		&i.ThemeMode,
		&i.PreferenceSource,
		&i.AdditionalPreferences,
		&i.UpdatedAt,
	)
	return &i, err
}
